(function(){'use strict';
var BOUNDS_KEY='welog-direct-split-bounds-v4', STICKER_KEY='welog-direct-stickers-v1';
function read(k,d){try{return JSON.parse(localStorage.getItem(k))||d}catch(e){return d}}
function write(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}}
function removeOldCropPanel(){document.querySelectorAll('.welog-split-area-control').forEach(function(n){n.remove()})}

/* CENTRAL IMAGE INFLUENCE AREA
   This is intentionally separate from artwork size. The overlay only exists after
   the user presses the "영역 자르기" button in the layout HUD. */
var boundsOverlay=null,boundsDrag=null,boundsEnabled=false;
function getBounds(){var b=read(BOUNDS_KEY,{top:0,right:0,bottom:0,left:0});return{top:+b.top||0,right:+b.right||0,bottom:+b.bottom||0,left:+b.left||0}}
function visualRect(){var split=document.querySelector('#sheet .center .pair-split');return split&&split.getBoundingClientRect()}
function influenceRect(){var r=visualRect(),b=getBounds();if(!r)return null;var out={left:r.left+b.left,top:r.top+b.top,right:r.right-b.right,bottom:r.bottom-b.bottom};if(out.right-out.left<30)out.right=out.left+30;if(out.bottom-out.top<30)out.bottom=out.top+30;return out}
function removeBoundsOverlay(){if(boundsOverlay){boundsOverlay.remove();boundsOverlay=null}boundsDrag=null}
function placeBoundsOverlay(){if(!boundsOverlay||!boundsEnabled)return;var r=influenceRect();if(!r)return;boundsOverlay.style.left=r.left+'px';boundsOverlay.style.top=r.top+'px';boundsOverlay.style.width=(r.right-r.left)+'px';boundsOverlay.style.height=(r.bottom-r.top)+'px'}
function makeBoundsOverlay(){if(boundsOverlay)return;boundsOverlay=document.createElement('div');boundsOverlay.className='direct-bounds-overlay-fixed';boundsOverlay.innerHTML='<b>중앙 이미지 영향 범위</b><i data-edge="t" title="위 범위"></i><i data-edge="r" title="오른쪽 범위"></i><i data-edge="b" title="아래 범위"></i><i data-edge="l" title="왼쪽 범위"></i><i data-corner="br" title="범위 조절"></i>';document.body.appendChild(boundsOverlay);
boundsOverlay.addEventListener('pointerdown',function(e){var h=e.target.closest('[data-edge],[data-corner]');if(!h)return;var vr=visualRect(),b=getBounds();if(!vr)return;e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();boundsDrag={edge:h.dataset.edge||h.dataset.corner,x:e.clientX,y:e.clientY,base:b,vr:vr};h.setPointerCapture&&h.setPointerCapture(e.pointerId)},true);
boundsOverlay.addEventListener('pointermove',function(e){if(!boundsDrag)return;e.preventDefault();e.stopPropagation();var d=boundsDrag,dx=e.clientX-d.x,dy=e.clientY-d.y,b={top:d.base.top,right:d.base.right,bottom:d.base.bottom,left:d.base.left},maxW=d.vr.width-30,maxH=d.vr.height-30;if(d.edge==='l')b.left=Math.max(-300,Math.min(maxW,d.base.left+dx));if(d.edge==='r')b.right=Math.max(-300,Math.min(maxW,d.base.right-dx));if(d.edge==='t')b.top=Math.max(-300,Math.min(maxH,d.base.top+dy));if(d.edge==='b')b.bottom=Math.max(-300,Math.min(maxH,d.base.bottom-dy));if(d.edge==='br'){b.right=Math.max(-300,Math.min(maxW,d.base.right-dx));b.bottom=Math.max(-300,Math.min(maxH,d.base.bottom-dy))}write(BOUNDS_KEY,b);placeBoundsOverlay();window.dispatchEvent(new CustomEvent('welog-influence-bounds-change',{detail:b}))},true);
boundsOverlay.addEventListener('pointerup',function(e){if(boundsDrag){boundsDrag=null;e.stopPropagation()}},true);boundsOverlay.addEventListener('pointercancel',function(){boundsDrag=null},true)}
function setBoundsMode(enabled,reset){boundsEnabled=!!enabled;removeOldCropPanel();if(reset){try{localStorage.removeItem(BOUNDS_KEY)}catch(e){}}if(!boundsEnabled){removeBoundsOverlay();return}if(!visualRect())return;makeBoundsOverlay();placeBoundsOverlay()}
window.addEventListener('welog-bounds-edit-mode',function(e){setBoundsMode(!!(e.detail&&e.detail.enabled),!!(e.detail&&e.detail.reset))});
function queueBounds(){if(boundsEnabled)requestAnimationFrame(placeBoundsOverlay)}window.addEventListener('resize',queueBounds);window.addEventListener('scroll',queueBounds,true);
/* Strip only obsolete visual-crop mutations. Never alter width, height, transform or positioning. */
function cleanupLegacyCrop(){removeOldCropPanel();var split=document.querySelector('#sheet .center .pair-split');if(!split)return;split.style.removeProperty('clip-path');split.removeAttribute('data-direct-crop');document.querySelectorAll('#sheet .direct-center-footprint-spacer,#sheet .direct-bounds-ui,#sheet .direct-crop-ui').forEach(function(n){n.remove()})}

function stickerLayer(){var sheet=document.getElementById('sheet');if(!sheet)return null;var l=sheet.querySelector('.direct-sticker-layer');if(!l){l=document.createElement('div');l.className='direct-sticker-layer';sheet.appendChild(l)}return l}
function getStickers(){return read(STICKER_KEY,[])}function saveStickers(v){write(STICKER_KEY,v)}function normalizeSticker(s){return{src:s.src,x:isFinite(+s.x)?+s.x:50,y:isFinite(+s.y)?+s.y:50,w:isFinite(+s.w)?+s.w:120,rot:isFinite(+s.rot)?+s.rot:0,locked:!!s.locked}}
function renderStickers(){var layer=stickerLayer();if(!layer)return;var arr=getStickers().map(normalizeSticker);saveStickers(arr);layer.innerHTML='';arr.forEach(function(s,i){var w=document.createElement('div');w.className='direct-sticker'+(s.locked?' is-locked':'');w.dataset.i=i;w.tabIndex=0;w.style.left=s.x+'%';w.style.top=s.y+'%';w.style.width=s.w+'px';w.style.transform='translate(-50%,-50%) rotate('+s.rot+'deg)';w.innerHTML='<img draggable="false"><div class="st-toolbar"><button type="button" class="st-lock">'+(s.locked?'🔒':'🔓')+'</button><label>크기 <input class="st-size" type="range" min="20" max="600" value="'+Math.round(s.w)+'"></label><label>회전 <input class="st-rot" type="range" min="-180" max="180" value="'+Math.round(s.rot)+'"></label><button type="button" class="st-del">×</button></div><i class="st-resize"></i><i class="st-rotate"></i>';w.querySelector('img').src=s.src;layer.appendChild(w)});bindStickerGestures(layer)}
function bindStickerGestures(layer){layer.querySelectorAll('.direct-sticker').forEach(function(w){var i=+w.dataset.i,mode='',sx=0,sy=0,base=null,pid=null;function update(s){w.style.left=s.x+'%';w.style.top=s.y+'%';w.style.width=s.w+'px';w.style.transform='translate(-50%,-50%) rotate('+s.rot+'deg)'}w.addEventListener('pointerdown',function(e){if(e.target.closest('.st-toolbar'))return;var arr=getStickers();if(!arr[i]||arr[i].locked)return;base=normalizeSticker(arr[i]);sx=e.clientX;sy=e.clientY;pid=e.pointerId;mode=e.target.closest('.st-resize')?'resize':e.target.closest('.st-rotate')?'rotate':'move';e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();w.setPointerCapture&&w.setPointerCapture(pid)},true);w.addEventListener('pointermove',function(e){if(!mode||e.pointerId!==pid)return;var arr=getStickers(),s=normalizeSticker(arr[i]),r=document.getElementById('sheet').getBoundingClientRect(),dx=e.clientX-sx,dy=e.clientY-sy;if(mode==='move'){s.x=Math.max(0,Math.min(100,base.x+dx/r.width*100));s.y=Math.max(0,Math.min(100,base.y+dy/r.height*100))}else if(mode==='resize')s.w=Math.max(20,Math.min(600,base.w+dx));else{var wr=w.getBoundingClientRect(),cx=wr.left+wr.width/2,cy=wr.top+wr.height/2;s.rot=Math.atan2(e.clientY-cy,e.clientX-cx)*180/Math.PI}arr[i]=s;saveStickers(arr);update(s);e.preventDefault();e.stopPropagation()},true);w.addEventListener('pointerup',function(){mode='';pid=null},true);w.addEventListener('pointercancel',function(){mode='';pid=null},true);w.querySelector('.st-del').onclick=function(e){e.stopPropagation();var a=getStickers();a.splice(i,1);saveStickers(a);renderStickers()};w.querySelector('.st-lock').onclick=function(e){e.stopPropagation();var a=getStickers();a[i]=normalizeSticker(a[i]);a[i].locked=!a[i].locked;saveStickers(a);renderStickers()};w.querySelector('.st-size').oninput=function(){var a=getStickers();if(a[i].locked)return;a[i]=normalizeSticker(a[i]);a[i].w=+this.value;saveStickers(a);update(a[i])};w.querySelector('.st-rot').oninput=function(){var a=getStickers();if(a[i].locked)return;a[i]=normalizeSticker(a[i]);a[i].rot=+this.value;saveStickers(a);update(a[i])}})}
function hookStickerUploads(){document.addEventListener('change',function(e){var inp=e.target;if(!inp.matches('[data-sticker-upload]')||!inp.files||!inp.files[0])return;var r=new FileReader();r.onload=function(){var a=getStickers();a.push({src:r.result,x:50,y:50,w:120,rot:0,locked:false});saveStickers(a);renderStickers();inp.value=''};r.readAsDataURL(inp.files[0])},true);document.addEventListener('click',function(e){var b=e.target.closest('[data-sticker-add]');if(!b)return;setTimeout(function(){var img=document.querySelectorAll('.sticker-gallery img')[+b.dataset.stickerAdd];if(!img)return;var a=getStickers();a.push({src:img.src,x:50,y:50,w:120,rot:0,locked:false});saveStickers(a);renderStickers()},0)},true)}
function boot(){var s=document.getElementById('sheet');if(!s)return;cleanupLegacyCrop();hookStickerUploads();renderStickers();document.addEventListener('input',function(e){if(e.target.closest&&e.target.closest('.direct-sticker'))return;cleanupLegacyCrop();queueBounds()},true);document.addEventListener('change',function(){cleanupLegacyCrop();queueBounds()},true)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();